package com.hospital.platform.bootstrap;
import java.util.Optional; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component public class BootstrapAdminInitializer implements ApplicationRunner { private final JdbcTemplate jdbc; private final PasswordEncoder encoder; private final String username; private final String password; public BootstrapAdminInitializer(JdbcTemplate jdbc,PasswordEncoder encoder,@Value("${hospital.bootstrap.admin-username:}") String username,@Value("${hospital.bootstrap.admin-password:}") String password){this.jdbc=jdbc;this.encoder=encoder;this.username=username;this.password=password;} public void run(ApplicationArguments args){if(username.isBlank()||password.length()<12)return;Integer count=jdbc.queryForObject("select count(*) from sys_user",Integer.class);if(count!=null&&count>0)return;jdbc.update("insert into sys_user(username,password_hash,display_name) values(?,?,?)",username,encoder.encode(password),"平台管理员");Long userId=jdbc.queryForObject("select id from sys_user where username=?",Long.class,username);Long roleId=jdbc.queryForObject("select id from sys_role where role_code='SUPER_ADMIN'",Long.class);jdbc.update("insert into sys_user_role(user_id,role_id) values(?,?)",userId,roleId);} }
